const nomi: Record<string, string> = {"milano": "Milano", "torino": "Torino", "bologna": "Bologna", "padova": "Padova", "verona": "Verona", "roma": "Roma", "firenze": "Firenze", "napoli": "Napoli", "bari": "Bari", "palermo": "Palermo"};

// Nota sul metodo, uguale in tutte le pagine della città.
export function notaMetodo(citta: string): string {
  return `Come sono raccolti i dati. AgenziaGiusta.it ha esaminato le prime dieci pagine dei risultati di Google per quattro ricerche: "agenzia di comunicazione ${citta}", "agenzia pubblicitaria ${citta}", "agenzia marketing ${citta}" e "web agency ${citta}" (rilevazione di ottobre 2026). Tra i siti trovati sono state considerate le agenzie con sede a ${citta} o in provincia e, per ciascuna, sono stati analizzati i servizi dichiarati sul sito. I risultati di Google cambiano nel tempo e da un utente all'altro: i dati sono una fotografia di quel momento e hanno valore indicativo. I dati descrivono le agenzie visibili su Google, non l'intero mercato cittadino.`;
}

// Le pagine di una città, nella forma dei testi locali.
export function datiCitta(slug: string): Record<string, TestiLocali> | undefined {
  const p = pagine[slug];
  if (!p) return undefined;
  return Object.fromEntries(
    Object.entries(p).map(([verticale, v]) => [
      verticale,
      {
        testo: v.testo,
        nota: notaMetodo(nomi[slug]),
        agenzie: v.agenzie.map((d): Agenzia => ({ nome: agenzie[d][0], url: agenzie[d][1] })),
      },
    ]),
  );
}
